<script setup lang="ts">import AdminLayout from '@/Layouts/AdminLayout.vue';import{Head,useForm}from'@inertiajs/vue3';const props=defineProps<{settings:any}>();const form=useForm({...props.settings});const save=()=>form.put(route('admin.settings.update'));</script>
<template><Head title="Settings"/><AdminLayout><h1 class="text-2xl font-bold">System settings</h1><p class="mt-1 text-sm text-slate-500">Credentials and server secrets are intentionally not editable here.</p><form class="mt-6 max-w-xl space-y-4 rounded-xl border bg-white p-6" @submit.prevent="save"><label class="flex items-center gap-2"><input v-model="form.allow_registration" true-value="1" false-value="0" type="checkbox"> Allow new registrations</label><label v-for="[key,label] in [['max_image_upload_kb','Maximum image upload (KB)'],['max_file_upload_kb','Maximum file upload (KB)'],['max_voice_upload_kb','Maximum voice upload (KB)'],['max_group_members','Maximum group members']]" :key="key" class="block text-sm font-medium">{{label}}<input v-model="form[key]" type="number" min="1" class="mt-1 block w-full rounded border p-2"></label><button :disabled="form.processing" class="rounded bg-slate-900 px-4 py-2 text-white">Save settings</button></form></AdminLayout></template>
